"""Ghana lotto 'classification chart' relationships (source: justlottoo.blogspot.com/p/charts.html,
compiled by Olugreenn). Each chart maps a number 1-90 to its related number.
Values outside 1-90 (e.g. Shadow/Code producing 00 or 91-99) are dropped."""

def _parse(s):
    d = {}
    for pair in s.split('|'):
        pair = pair.strip()
        if not pair or '=' not in pair: continue
        a, b = pair.split('=')
        try: a, b = int(a), int(b)
        except ValueError: continue
        if 1 <= a <= 90 and 1 <= b <= 90: d[a] = b
    return d

