CHARTS = {'bonanza':BONANZA,'counterpart':COUNTERPART,'malta':MALTA,'string_key':STRING_KEY,
          'shadow':SHADOW,'partner':PARTNER,'equivalent':EQUIVALENT,'code':CODE,'turning':TURNING}

def related(n):
    """All chart-related numbers of n (deduplicated)."""
    out = set()
    for c in CHARTS.values():
        if n in c: out.add(c[n])
    return out
